/// A DOF component, in FK's order (UX, UY, UZ, RX, RY, RZ).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Component {
    Ux,
    Uy,
    Uz,
    Rx,
    Ry,
    Rz,
}

impl Component {
    pub const ALL: [Component; 6] = [
        Component::Ux,
        Component::Uy,
        Component::Uz,
        Component::Rx,
        Component::Ry,
        Component::Rz,
    ];

    pub fn index(self) -> usize {
        self as usize
    }

    pub fn from_index(index: usize) -> Self {
        Self::ALL[index]
    }

    pub(crate) fn is_translation(self) -> bool {
        self.index() < 3
    }
}

/// A DOF: node `k` owns global DOFs 6k..6k+5.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Dof {
    pub node: u32,
    pub component: Component,
}

impl Dof {
    pub fn global(self) -> usize {
        self.node as usize * DOF_PER_NODE + self.component.index()
    }

    pub fn from_global(global: usize) -> Self {
        Self {
            node: (global / DOF_PER_NODE) as u32,
            component: Component::from_index(global % DOF_PER_NODE),

fn rejection_reason(
    rejection: Option<Rejection>,
    layout: &[QuantityMeta],
    group: &GroupPrep,
) -> AttemptReason {
    let row = |index: usize| layout[index];
    match rejection {
        Some(Rejection::StopRule { index }) => AttemptReason::StopRule {
            quantity: row(index).id,
            body: row(index).body,
            kind: row(index).kind,
        },
        Some(Rejection::VerificationEstimate { index }) => AttemptReason::VerificationEstimate {
            quantity: row(index).id,
            body: row(index).body,
            kind: row(index).kind,
        },
        Some(Rejection::Uc { block }) => AttemptReason::Uc {
            body: group.blocks.body[block],
        },
        Some(Rejection::Theta { block }) => AttemptReason::Theta {
            body: group.blocks.body[block],
        },
        Some(Rejection::GValidity { member }) => AttemptReason::GValidity { member },
        Some(Rejection::Charge { index }) => AttemptReason::Charge {
            quantity: row(index).id,
            body: row(index).body,
            kind: row(index).kind,
        },
        None => AttemptReason::VerificationFailed,
    }

